       while stack:
        y,x=stack.pop(); comp.add((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         p=y+dy,x+dx
         if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:
          seen.add(p);stack.append(p)
       y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
       # flood zeros from bbox edge
       outside=set(); q=[]
       for y in range(y0,y1+1):
        for x in range(x0,x1+1):
