          outside.add((y,x));q.append((y,x))
       while q:
        y,x=q.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         p=y+dy,x+dx
         if y0<=p[0]<=y1 and x0<=p[1]<=x1 and grid[p[0]][p[1]]==0 and p not in outside:
          outside.add(p);q.append(p)
       holes={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if grid[y][x]==0 and (y,x) not in outside}
       if not holes: continue
       for y,x in holes: out[y][x]=3
       # Draw outline, allowing existing figure cells to overwrite it afterward.
       for y,x in comp:
        for dy in (-1,0,1):
         for dx in (-1,0,1):
          yy,xx=y+dy,x+dx
          if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in holes: out[yy][xx]=2
    # Restore all original figure pixels so outlines never erase another figure.
    for y in range(h):
      for x in range(w):
       if grid[y][x]==1: out[y][x]=1
    return out

